 WHERE NOT EXISTS (
       SELECT 1 FROM t_prc_component_prices p
        WHERE p.comp_cd   = v.comp_cd
          AND p.apply_ymd = v.apply_ymd
          AND p.siz_cd    = v.siz_cd
          AND p.mat_cd    = v.mat_cd
          AND p.min_qty   = v.min_qty
          AND 
p.plt_siz_cd IS NULL          AND p.clr_cd IS NULL          AND p.proc_cd IS NULL          AND p.opt_cd IS NULL          AND p.print_opt_cd IS NULL          AND p.coat_side_cnt IS NULL          AND p.spot_side_cnt IS NULL          AND p.bdl_qty IS NULL          AND p.page_cnt IS NULL          AND p.siz_width IS NULL          AND p.siz_height IS NULL          AND p.dim_vals IS NULL);

\echo '=== 3. 적용 후 사이즈별 행수 — 057=8자재 288 · 058=288 · 067=288 기대 ==='
SELECT siz_cd, count(*) AS rows FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT'
 GROUP BY 1 ORDER BY 1;
SELECT count(*) AS total_rows FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT';

\echo '=== 4. 사후 셀대조용 — 넣은 행의 자재/수량 축이 형제와 같은지 ==='
SELECT siz_cd, count(DISTINCT mat_cd) AS mats, count(DISTINCT min_qty) AS qtys
  FROM t_prc_component_prices WHERE comp_cd='STK_KISSCUT_PRINT'
 GROUP BY 1 ORDER BY 1;

\echo '=== 5. 다른 구성요소/사이즈 무변경 확인 — 고아 518·519 는 576행 그대로 ==='
SELECT siz_cd, count(*) FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT' AND siz_cd IN ('SIZ_000518','SIZ_000519')
 GROUP BY 1 ORDER BY 1;

\echo '=== 6. rollback 문 검증 — DELETE 648 기대 ==='
DELETE FROM t_prc_component_prices
 WHERE comp_cd = 'STK_KISSCUT_PRINT'
   AND apply_ymd = '2026-09-02'
   AND note LIKE '권위 스티커 r% c1%'
   AND ( (siz_cd = 'SIZ_000057' AND mat_cd IN ('MAT_000609','MAT_000611'))
      OR  siz_cd IN ('SIZ_000058','SIZ_000067') );

\echo '=== 7. 되돌린 뒤 행수 — 0번과 같아야 한다 ==='
SELECT siz_cd, count(*) AS rows FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT'
 GROUP BY 1 ORDER BY 1;
SELECT count(*) AS total_rows FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT';

\echo '=== 8. ROLLBACK ==='
ROLLBACK;

\echo '=== 9. 트랜잭션 밖 재확인 — 라이브 원래대로여야 한다 ==='
SELECT siz_cd, count(*) AS rows FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT'
 GROUP BY 1 ORDER BY 1;
SELECT count(*) AS total_rows FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT';
